elements */		/* [1] */		{119, 288, 139, 348},		Button {			enabled,			"Save"		},		/* [2] */		{119, 215, 139, 275},		Button {			enabled,			"Cancel"		},		/* [3] */		{119, 72, 139, 156},		Button {			enabled,			"Don't Save"		},		/* [4] */		{10, 75, 106, 348},		StaticText {			disabled,			"This document contains new Publishers. You must save this document to keep them."			"\n\n"			"Save '^0' before ^1?"		},		/* [6] */		{10, 20, 42, 52},		Icon {			disabled,			cautionIcon		}	}};/* Used when a document has multiple publishers to the same edition. */resource 'DITL' (phMultPublisherWrn,#if qNames	"phMultPublisherWrn",#endif	purgeable) {	{	/* array DITLarray: 4 elements */		/* [1] */		{135, 288, 155, 348},		Button {			enabled,			"OK"		},		/* [2] */		{10, 75, 122, 348},		StaticText {			disabled,			"There is another Publisher open to the Edition '^0.'"			"\n\n"			"If there is more than one Publisher to an Edition, the Edition's contents aren't predictable."		},		/* [4] */		{10, 20, 42, 52},		Icon {			disabled,			cautionIcon		}	}};/* Used when a document tries to save multiple publishers to the same edition. */resource 'DITL' (phSavingMultPublisherWrn,#if qNames	"phSavingMultPublisherWrn",#endif	purgeable) {	{	/* array DITLarray: 4 elements */		/* [1] */		{135, 288, 155, 348},		Button {			enabled,			"OK"		},		/* [2] */		{10, 75, 122, 348},		StaticText {			disabled,			"'^1' contains two Publishers to the Edition '^0.'"			"\n\n"			"If there is more than one Publisher to an Edition, the Edition's contents aren't predictable."		},		/* [4] */		{10, 20, 42, 52},		Icon {			disabled,			cautionIcon		}	}};resource 'ALRT' (phNewPublisherAlert,#if qNames	"phNewPublisherAlert",#endif	purgeable) {	{86, 60, 235, 418},	phNewPublisherAlert,	{	/* array: 4 elements */		/* [1] */		OK, visible, silent,		/* [2] */		OK, visible, silent,		/* [3] */		OK, visible, silent,		/* [4] */		OK, visible, silent	},	alertPositionMainScreen};resource 'ALRT' (phMultPublisherWrn,#if qNames	"phMultPublisherWrn",#endif	purgeable) {	{100, 110, 265, 468},	phMultPublisherWrn,	{	/* array: 4 elements */		/* [1] */		OK, visible, silent,		/* [2] */		OK, visible, silent,		/* [3] */		OK, visible, silent,		/* [4] */		OK, visible, silent	},	alertPositionMainScreen};resource 'ALRT' (phSavingMultPublisherWrn,#if qNames	"phSavingMultPublisherWrn",#endif	purgeable) {	{100, 110, 265, 468},	phSavingMultPublisherWrn,	{	/* array: 4 elements */		/* [1] */		OK, visible, silent,		/* [2] */		OK, visible, silent,		/* [3] */		OK, visible, silent,		/* [4] */		OK, visible, silent	},	alertPositionMainScreen};